// Function: Sunset/Sunrise Anchor Controller
// Tracks position (GPS / default), Auto mode, and switches Anchor Light automatically at Sunset/Sunrise with buffers.

const ON_BUFFER_MIN = 15;   // Turn ON 15 minutes before sunset
const OFF_BUFFER_MIN = 30;  // Turn OFF 30 minutes after sunrise

// Default fallback coordinates if GPS is unavailable
const DEFAULT_LAT = 43.5;   // Mediterranean / Adriatic cruising ground
const DEFAULT_LON = 16.2;

if (msg.topic === 'auto') {
    const autoVal = Number(msg.payload) === 1 ? 1 : 0;
    context.set('auto_mode', autoVal);
} else if (msg.topic === 'state') {
    const stateVal = Number(msg.payload) === 1 ? 1 : 0;
    context.set('current_state', stateVal);
} else if (msg.topic === 'lat' && typeof msg.payload === 'number' && !isNaN(msg.payload) && msg.payload >= -90 && msg.payload <= 90) {
    context.set('latitude', msg.payload);
} else if (msg.topic === 'lon' && typeof msg.payload === 'number' && !isNaN(msg.payload) && msg.payload >= -180 && msg.payload <= 180) {
    context.set('longitude', msg.payload);
}

const autoMode = context.get('auto_mode') === 1;
const currentState = context.get('current_state');
const lat = typeof context.get('latitude') === 'number' ? context.get('latitude') : DEFAULT_LAT;
const lon = typeof context.get('longitude') === 'number' ? context.get('longitude') : DEFAULT_LON;

if (!autoMode) {
    node.status({ fill: "grey", shape: "ring", text: "Manual Mode (Auto disabled)" });
    return null;
}

function calcSunTimes(d, latDeg, lonDeg) {
    const rad = Math.PI / 180;
    const deg = 180 / Math.PI;
    const start = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    const dayOfYear = Math.floor((d - start) / 86400000) + 1;
    const gamma = 2 * Math.PI / 365 * (dayOfYear - 1 + 0.5);
    const eqtime = 229.18 * (0.000075 + 0.001868 * Math.cos(gamma) - 0.032077 * Math.sin(gamma)
                           - 0.014615 * Math.cos(2 * gamma) - 0.040849 * Math.sin(2 * gamma));
    const decl = 0.006918 - 0.399912 * Math.cos(gamma) + 0.070257 * Math.sin(gamma)
               - 0.006758 * Math.cos(2 * gamma) + 0.000907 * Math.sin(2 * gamma)
               - 0.002697 * Math.cos(3 * gamma) + 0.00148 * Math.sin(3 * gamma);
    const zenith = 90.833 * rad;
    const cosHA = (Math.cos(zenith) / (Math.cos(latDeg * rad) * Math.cos(decl))) - (Math.tan(latDeg * rad) * Math.tan(decl));
    if (cosHA > 1) return { polarNight: true };
    if (cosHA < -1) return { midnightSun: true };
    const ha = Math.acos(cosHA) * deg;
    const sunriseMin = 720 - 4 * (lonDeg + ha) - eqtime;
    const sunsetMin = 720 - 4 * (lonDeg - ha) - eqtime;
    const sunrise = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), 0, sunriseMin, 0));
    const sunset = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), 0, sunsetMin, 0));
    return { sunrise, sunset };
}

const now = new Date();
const today = calcSunTimes(now, lat, lon);
const yesterday = calcSunTimes(new Date(now.getTime() - 86400000), lat, lon);

let isNight = false;
if (today.polarNight) {
    isNight = true;
} else if (today.midnightSun) {
    isNight = false;
} else {
    const todaySunsetBuffered = new Date(today.sunset.getTime() - ON_BUFFER_MIN * 60000);
    const todaySunriseBuffered = new Date(today.sunrise.getTime() + OFF_BUFFER_MIN * 60000);
    const yesterdaySunsetBuffered = new Date(yesterday.sunset.getTime() - ON_BUFFER_MIN * 60000);

    if (now >= todaySunsetBuffered || now < todaySunriseBuffered || (now >= yesterdaySunsetBuffered && now < todaySunriseBuffered)) {
        isNight = true;
    }
}

const desiredState = isNight ? 1 : 0;

function formatHHMM(d) {
    return ("0" + d.getUTCHours()).slice(-2) + ":" + ("0" + d.getUTCMinutes()).slice(-2) + " UTC";
}

const gpsText = (typeof context.get('latitude') === 'number') ? "GPS (" + lat.toFixed(2) + "," + lon.toFixed(2) + ")" : "Default (" + lat + "," + lon + ")";

if (isNight) {
    node.status({ fill: "blue", shape: "dot", text: "Auto ON (Night: Sunset ~" + (today.sunset ? formatHHMM(today.sunset) : "") + " | " + gpsText + ")" });
} else {
    node.status({ fill: "yellow", shape: "ring", text: "Auto OFF (Day: Sunrise ~" + (today.sunrise ? formatHHMM(today.sunrise) : "") + " | " + gpsText + ")" });
}

if (desiredState !== currentState) {
    context.set('current_state', desiredState);
    return {
        payload: desiredState,
        topic: "anchor_light_state",
        reason: isNight ? "Sunset trigger" : "Sunrise trigger",
        location: { lat, lon, source: (typeof context.get('latitude') === 'number' ? 'gps' : 'default') },
        times: today
    };
}

return null;
